import { useEffect, useMemo, useState } from 'react';
import { ArrowLeft, Boxes, CheckCircle2, ClipboardList, FileText, ImagePlus, PackagePlus, Pencil, Plus, Printer, Save, Scissors, Search, ShieldCheck, Trash2, X } from 'lucide-react';
import { api, formatCurrency } from '../lib/api';
import type { Product } from '../types';
import { draftKitAnalysis } from '../lib/kitAnalysis';

type Any = any;
const n = (value: unknown) => Number(value) || 0;
const unitLabel = (unit: string) => unit === 'metre' ? 'm' : unit === 'm2' ? 'm²' : 'adet';
const norm = (value: unknown) => String(value || '').toLowerCase().replace(/\s+/g, '').replace(/×/g, 'x');

function ImagePicker({ value, onChange, label = 'Görsel ekle' }: { value?: string; onChange: (file: File | null) => void; label?: string }) {
  const [preview, setPreview] = useState<string | undefined>(value);
  return <label className="group relative flex min-h-28 cursor-pointer items-center justify-center overflow-hidden rounded-xl border border-dashed bg-slate-50 p-3 text-center text-sm text-slate-500 hover:border-cyan-500 hover:bg-cyan-50">
    {preview ? <img src={preview} alt="Seçilen görsel" className="absolute inset-0 h-full w-full object-cover" /> : <span><ImagePlus className="mx-auto mb-1 h-5 w-5" />{label}<small className="mt-1 block">JPG, PNG veya WEBP · maks. 8 MB</small></span>}
    {preview && <span className="relative rounded bg-slate-900/75 px-2 py-1 text-xs font-bold text-white">Görseli değiştir</span>}
    <input className="sr-only" type="file" accept="image/jpeg,image/png,image/webp" onChange={event => {
      const file = event.target.files?.[0] || null;
      if (file) setPreview(URL.createObjectURL(file));
      onChange(file);
    }} />
  </label>;
}

export function EnhancedKitBuilder({ kit, profiles, products, complementary, back, save }: Any) {
  const [data, setData] = useState<Any>({ ...kit, items: kit.items || [], cuts: kit.cuts || [], complementary_items: kit.complementary_items || [] });
  const [productQuery, setProductQuery] = useState('');
  const [complementQuery, setComplementQuery] = useState('');
  const [image, setImage] = useState<File | null>(null);
  const [saving, setSaving] = useState(false);
  const set = (key: string, value: unknown) => setData((old: Any) => ({ ...old, [key]: value }));
  const update = (group: string, index: number, key: string, value: unknown) => {
    const rows = [...data[group]]; rows[index] = { ...rows[index], [key]: value }; set(group, rows);
  };
  const selectedProfile = profiles.find((profile: Any) => profile.id === data.profile_id);
  const live = useMemo(() => draftKitAnalysis(data, selectedProfile, products, complementary), [data, selectedProfile, products, complementary]);
  const dirty = useMemo(() => JSON.stringify(data) !== JSON.stringify({ ...kit, items: kit.items || [], cuts: kit.cuts || [], complementary_items: kit.complementary_items || [] }) || Boolean(image), [data, image, kit]);
  const goBack = () => {
    if (dirty && !confirm('Kaydedilmemiş kit değişiklikleri var. Çıkmak istiyor musunuz?')) return;
    back();
  };
  const matchesSelectedProfile = (product: Any) => {
    if (!selectedProfile) return true;
    const profileSize = norm(selectedProfile.dimension);
    const productSize = norm(product.normalized_pipe_size || product.pipe_size || product.size || product.size_code);
    const profileShape = norm(selectedProfile.shape);
    const productShape = norm(product.normalized_tube_type || product.tube_type_code || product.form_code || product.model);
    const sizeMatches = !profileSize || !productSize || profileSize === productSize || productSize.includes(profileSize) || profileSize.includes(productSize);
    const shapeMatches = !profileShape || !productShape || productShape.includes(profileShape) || profileShape.includes(productShape);
    return sizeMatches && shapeMatches;
  };
  const addProduct = (product: Any) => {
    if (!data.items.some((item: Any) => item.product_id === product.id)) {
      set('items', [...data.items, { product_id: product.id, title: product.title, name: product.name, sku: product.sku, central_stock: product.central_stock, purchase_cost: product.purchase_cost, sale_price: product.sale_price, quantity: 1 }]);
    }
    setProductQuery('');
  };
  const addComplement = (product: Any) => {
    if (!data.complementary_items.some((item: Any) => item.complementary_product_id === product.id)) {
      set('complementary_items', [...data.complementary_items, { complementary_product_id: product.id, product_name_snapshot: product.name, unit_snapshot: product.unit, purchase_price_snapshot: product.purchase_price, unit_weight_kg_snapshot: product.unit_weight_kg, supplier_snapshot: product.supplier, quantity: 1 }]);
    }
    setComplementQuery('');
  };
  const foundProducts = products.filter((product: Any) => matchesSelectedProfile(product) && (!productQuery || [product.title, product.name, product.sku, product.pipe_size, product.normalized_tube_type].some(value => String(value || '').toLowerCase().includes(productQuery.toLowerCase())))).slice(0, 12);
  const foundComplements = complementary.filter((product: Any) => !complementQuery || [product.name, product.category, product.supplier].some(value => String(value || '').toLowerCase().includes(complementQuery.toLowerCase()))).slice(0, 8);
  const stockLengthM = n(selectedProfile?.stock_length_mm) ? n(selectedProfile.stock_length_mm) / 1000 : 6;
  const totalCuts = (data.cuts || []).reduce((sum: number, cut: Any) => sum + n(cut.quantity), 0);
  const wasteRate = stockLengthM && live.profileMeters ? Math.max(0, ((Math.ceil(live.profileMeters / stockLengthM) * stockLengthM - live.profileMeters) / Math.max(0.001, Math.ceil(live.profileMeters / stockLengthM) * stockLengthM)) * 100) : 0;
  const submit = async () => {
    if (!data.name || !data.profile_id) return alert('Kit adı ve profil seçimi zorunludur.');
    setSaving(true);
    try { await save(data, image); } catch (error: Any) { alert(error.message || 'Kit kaydedilemedi.'); } finally { setSaving(false); }
  };
  return <div className="space-y-5">
    <div className="flex items-center justify-between gap-3"><button onClick={goBack} className="text-sm font-bold text-slate-600"><ArrowLeft className="mr-1 inline h-4 w-4" />Kitlere dön</button><button disabled={saving} onClick={submit} className="rounded-xl bg-cyan-700 px-5 py-2.5 text-sm font-bold text-white shadow-sm disabled:opacity-50"><Save className="mr-2 inline h-4 w-4" />{saving ? 'Kaydediliyor...' : 'Kaydet ve hesapla'}</button></div>
    <KitStepper />
    <div className="grid items-start gap-6 xl:grid-cols-[minmax(0,1fr)_360px]">
      <div className="space-y-5">
        <BuilderCard icon={ClipboardList} step="1" title="Kit bilgileri" subtitle="Temel bilgiler">
          <div className="grid gap-4 lg:grid-cols-[1fr_240px]"><div className="space-y-3"><div className="grid gap-3 md:grid-cols-2"><Field label="Kit adı *"><input value={data.name || ''} onChange={e => set('name', e.target.value)} placeholder="20×20 Kare Profil Çerçeve Kiti" className="w-full rounded-lg border p-3" /></Field><Field label="Kit kodu"><input value={data.code || ''} onChange={e => set('code', e.target.value)} placeholder="KIT-2020-001" className="w-full rounded-lg border p-3" /></Field></div><Field label="Müşteri teklifinde görünen açıklama"><textarea value={data.description || ''} onChange={e => set('description', e.target.value)} placeholder="Kısa ve profesyonel açıklama girin." className="h-20 w-full rounded-lg border p-3" /></Field></div><ImagePicker value={data.cover_image} onChange={setImage} label={data.id ? 'Kit fotoğrafını değiştir' : 'Kit fotoğrafı ekle'} /></div>
        </BuilderCard>
        <BuilderCard icon={ShieldCheck} step="2" title="Profil seçimi" subtitle="Profil özellikleri">
          <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4"><Field label="Profil türü / varyant"><select value={data.profile_id || ''} onChange={e => { const profile = profiles.find((item: Any) => item.id === e.target.value); setData({ ...data, profile_id: e.target.value, profile_offer_id: profile?.offers?.find((offer: Any) => offer.is_preferred)?.id || '' }); }} className="w-full rounded-lg border p-3"><option value="">Profil seçin *</option>{profiles.map((profile: Any) => <option value={profile.id} key={profile.id}>{profile.shape} · {profile.dimension} · {profile.thickness || 'std'} · {profile.name}</option>)}</select></Field><Field label="Profil malzemesi"><input readOnly value={selectedProfile?.material || 'Profil seçin'} className="w-full rounded-lg border bg-slate-50 p-3 text-slate-600" /></Field><Field label="Et kalınlığı"><input readOnly value={selectedProfile?.thickness || '—'} className="w-full rounded-lg border bg-slate-50 p-3 text-slate-600" /></Field><Field label="Tedarikçi / fiyat"><select value={data.profile_offer_id || ''} onChange={e => set('profile_offer_id', e.target.value)} className="w-full rounded-lg border p-3"><option value="">Varsayılan profil fiyatı</option>{selectedProfile?.offers?.map((offer: Any) => <option key={offer.id} value={offer.id}>{offer.supplier} · {formatCurrency(n(offer.price_per_meter))}/m</option>)}</select></Field></div>
          <div className="mt-4 grid overflow-hidden rounded-xl border border-cyan-200 bg-cyan-50 text-sm md:grid-cols-4"><InfoCell label="Profil ebatı" value={selectedProfile?.dimension || '—'} /><InfoCell label="Ham boy" value={`${n(selectedProfile?.stock_length_mm) || 6000} mm`} /><InfoCell label="Birim alış fiyatı" value={`${formatCurrency(n(selectedProfile?.effective_price_per_meter || selectedProfile?.price_per_meter))} / m`} /><InfoCell label="Kaplama / renk" value={`${selectedProfile?.finish || 'Standart'} / ${selectedProfile?.color || '—'}`} /></div>
        </BuilderCard>
        <BuilderCard icon={Boxes} step="3" title="Bağlantı elemanları" subtitle={selectedProfile ? `${selectedProfile.dimension} profile uygun katalog` : 'Profil seçince katalog daralır'}>
          <CatalogGrid query={productQuery} setQuery={setProductQuery} results={foundProducts} add={addProduct} complement={false} />
          <SelectedLines items={data.items} update={(index: number, value: unknown) => update('items', index, 'quantity', value)} remove={(index: number) => set('items', data.items.filter((_: Any, i: number) => i !== index))} />
          <CompatibilityNotice rows={live.compatibility} />
        </BuilderCard>
        <BuilderCard icon={Scissors} step="4" title="Profil kesimleri" subtitle="Kesim listesi">
          <div className="mb-3 grid gap-2 md:grid-cols-4"><InfoPill label="Toplam kesim" value={`${totalCuts} adet`} /><InfoPill label="Toplam metraj" value={`${live.profileMeters.toFixed(2)} m`} /><InfoPill label="Tahmini ham profil" value={`${Math.ceil(live.profileMeters / Math.max(0.001, stockLengthM)) || 0} adet (${stockLengthM.toFixed(2)} m)`} /><InfoPill label="Tahmini atık" value={`%${wasteRate.toFixed(1)}`} /></div>
          <div className="overflow-x-auto"><table className="w-full min-w-[720px] text-sm"><thead className="bg-slate-50 text-xs uppercase text-slate-500"><tr><th className="p-2">#</th><th className="p-2 text-left">Kesim adı</th><th className="p-2 text-right">Uzunluk (mm)</th><th className="p-2 text-right">Adet</th><th className="p-2 text-right">Toplam (m)</th><th className="p-2 text-left">Açıklama</th><th className="p-2" /></tr></thead><tbody>{data.cuts.map((cut: Any, index: number) => <tr key={index} className="border-b"><td className="p-2 text-slate-400">{index + 1}</td><td className="p-2"><input value={cut.label || ''} onChange={e => update('cuts', index, 'label', e.target.value)} placeholder="Dikey profil" className="w-full rounded border p-2" /></td><td className="p-2 text-right"><input type="number" min="1" value={cut.length_mm} onChange={e => update('cuts', index, 'length_mm', e.target.value)} className="w-28 rounded border p-2 text-right" /></td><td className="p-2 text-right"><input type="number" min="1" value={cut.quantity} onChange={e => update('cuts', index, 'quantity', e.target.value)} className="w-20 rounded border p-2 text-right" /></td><td className="p-2 text-right font-bold">{((n(cut.length_mm) * n(cut.quantity)) / 1000).toFixed(2)}</td><td className="p-2"><input value={cut.notes || ''} onChange={e => update('cuts', index, 'notes', e.target.value)} placeholder="Sol & sağ dikey" className="w-full rounded border p-2" /></td><td className="p-2 text-right"><button onClick={() => set('cuts', data.cuts.filter((_: Any, i: number) => i !== index))} className="text-red-500" aria-label="Kesimi sil"><Trash2 className="h-4 w-4" /></button></td></tr>)}{!data.cuts.length && <tr><td colSpan={7} className="p-6 text-center text-slate-400">Henüz kesim eklenmedi.</td></tr>}</tbody></table></div><button onClick={() => set('cuts', [...data.cuts, { label: '', length_mm: '', quantity: 1, notes: '' }])} className="mt-3 rounded-xl border border-cyan-300 px-4 py-2 text-sm font-bold text-cyan-700"><Plus className="mr-1 inline h-4 w-4" />Kesim ekle</button>
        </BuilderCard>
        <BuilderCard icon={PackagePlus} step="5" title="Tamamlayıcı ürünler" subtitle={`${data.complementary_items.length || 0} ürün seçildi`}>
          <CatalogGrid query={complementQuery} setQuery={setComplementQuery} results={foundComplements} add={addComplement} complement />
          <SelectedLines items={data.complementary_items} update={(index: number, value: unknown) => update('complementary_items', index, 'quantity', value)} remove={(index: number) => set('complementary_items', data.complementary_items.filter((_: Any, i: number) => i !== index))} complement />
        </BuilderCard>
      </div>
      <BuilderCostPanel analysis={live} data={data} set={set} saving={saving} submit={submit} />
    </div>
  </div>;
}

function KitStepper() {
  const steps = [['1', 'Kit Bilgileri', 'Temel bilgiler'], ['2', 'Profil Seçimi', 'Profil özellikleri'], ['3', 'Bağlantı Elemanları', 'Bağlantı parçaları'], ['4', 'Profil Kesimleri', 'Kesim listesi'], ['5', 'Tamamlayıcı Ürünler', 'Ek ürünler'], ['6', 'Maliyet & Kaydet', 'Hesapla ve kaydet']];
  return <div className="overflow-x-auto rounded-2xl border bg-white p-4 shadow-sm"><div className="flex min-w-[980px] items-center gap-3">{steps.map(([no, title, sub], index) => <div key={no} className="flex flex-1 items-center gap-3"><div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-full border text-sm font-black ${index === 0 ? 'border-blue-600 bg-blue-600 text-white shadow-md shadow-blue-200' : 'border-slate-200 bg-slate-50 text-slate-700'}`}>{no}</div><div><b className="text-sm text-slate-900">{title}</b><p className="text-xs text-slate-500">{sub}</p></div>{index < steps.length - 1 && <div className="ml-auto h-px flex-1 border-t border-dashed border-slate-300" />}</div>)}</div></div>;
}

function BuilderCard({ icon: Icon, step, title, subtitle, children }: Any) {
  return <section className="rounded-2xl border bg-white p-5 shadow-sm"><div className="mb-4 flex items-start justify-between gap-3"><div className="flex items-start gap-3"><div className="rounded-xl bg-cyan-50 p-2 text-cyan-700"><Icon className="h-5 w-5" /></div><div><h3 className="font-black text-slate-900">{title}</h3><p className="mt-0.5 text-sm text-slate-500">{subtitle}</p></div></div><span className="rounded-full bg-slate-50 px-2.5 py-1 text-xs font-black text-slate-500">Adım {step}</span></div>{children}</section>;
}

function Field({ label, children }: Any) {
  return <label className="block text-xs font-bold text-slate-500">{label}<div className="mt-1">{children}</div></label>;
}

function InfoCell({ label, value }: { label: string; value: string }) {
  return <div className="border-cyan-200 p-3 md:border-r last:border-r-0"><p className="text-xs font-bold text-slate-500">{label}</p><b className="mt-1 block text-slate-900">{value}</b></div>;
}

function InfoPill({ label, value }: { label: string; value: string }) {
  return <div className="rounded-xl border bg-slate-50 px-4 py-2"><p className="text-xs font-bold text-slate-500">{label}</p><b className="text-sm text-slate-900">{value}</b></div>;
}

function CatalogGrid({ query, setQuery, results, add, complement = false }: Any) {
  return <div><div className="mb-3 flex flex-col gap-2 md:flex-row md:items-center"><div className="relative max-w-md flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Katalogda ara..." className="w-full rounded-lg border py-2.5 pl-9 text-sm" /></div><span className="ml-auto text-xs font-bold text-slate-500">{results.length} sonuç</span></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">{results.map((item: Any) => <div key={item.id} className="flex gap-3 rounded-xl border bg-white p-3 shadow-sm"><div className="flex h-14 w-14 shrink-0 items-center justify-center overflow-hidden rounded-lg bg-slate-100">{item.cover_image ? <img src={item.cover_image} alt="" className="h-full w-full object-cover" /> : <Boxes className="h-5 w-5 text-slate-400" />}</div><div className="min-w-0 flex-1"><b className="line-clamp-2 text-xs text-slate-900">{item.title || item.name}</b><p className="mt-1 truncate text-[11px] text-slate-400">{complement ? [item.category, item.supplier].filter(Boolean).join(' · ') : [item.sku, item.pipe_size || item.normalized_pipe_size].filter(Boolean).join(' · ')}</p><div className="mt-2 flex items-center justify-between"><span className="rounded bg-emerald-50 px-2 py-0.5 text-[10px] font-bold text-emerald-700">{complement ? `${formatCurrency(n(item.purchase_price))}/${unitLabel(item.unit)}` : `stok ${item.central_stock || item.total_stock || 0}`}</span><button onClick={() => add(item)} className="rounded-lg border border-blue-300 px-3 py-1 text-[11px] font-bold text-blue-700 hover:bg-blue-50"><Plus className="mr-1 inline h-3 w-3" />Ekle</button></div></div></div>)}{!results.length && <div className="rounded-xl border border-dashed p-6 text-center text-sm text-slate-400 md:col-span-2 xl:col-span-4">Katalogda uygun ürün bulunamadı.</div>}</div></div>;
}

function SelectedLines({ items, update, remove, complement = false }: Any) {
  return <div className="mt-4 overflow-x-auto rounded-xl border"><table className="w-full min-w-[760px] text-sm"><thead className="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th className="p-3">Ürün adı</th><th className="p-3">Kod</th><th className="p-3 text-right">Miktar</th><th className="p-3 text-right">Birim</th><th className="p-3 text-right">Birim fiyat</th><th className="p-3 text-right">Tutar</th><th className="p-3" /></tr></thead><tbody>{items.map((item: Any, index: number) => { const unitCost = complement ? n(item.purchase_price_snapshot ?? item.purchase_price) : n(item.purchase_cost); return <tr key={item.product_id || item.complementary_product_id || index} className="border-t"><td className="p-3 font-bold">{item.title || item.name || item.product_name_snapshot}</td><td className="p-3 text-xs text-slate-400">{item.sku || item.supplier_snapshot || '—'}</td><td className="p-3 text-right"><input type="number" step="0.01" min="0.01" value={item.quantity} onChange={e => update(index, e.target.value)} className="w-20 rounded border p-2 text-right" /></td><td className="p-3 text-right">{complement ? unitLabel(item.unit_snapshot || item.unit) : 'adet'}</td><td className="p-3 text-right">{formatCurrency(unitCost)}</td><td className="p-3 text-right font-black">{formatCurrency(n(item.quantity) * unitCost)}</td><td className="p-3 text-right"><button onClick={() => remove(index)} className="text-red-500" aria-label="Satırı sil"><Trash2 className="h-4 w-4" /></button></td></tr>; })}{!items.length && <tr><td colSpan={7} className="p-6 text-center text-slate-400">{complement ? 'Henüz tamamlayıcı ürün eklenmedi.' : 'Henüz bağlantı elemanı eklenmedi.'}</td></tr>}</tbody></table></div>;
}

function BuilderCostPanel({ analysis, data, set, saving, submit }: Any) {
  const breakdown = [['Profiller', analysis.profileCost], ['Bağlantı elemanları', analysis.partsCost], ['Tamamlayıcı ürünler', analysis.complementaryCost], ['Kesim', n(data.cutting_cost)], ['İşçilik', n(data.labour_cost)], ['Paketleme', n(data.packaging_cost)], ['Ticari giderler', n(data.payment_cost) + n(data.shipping_cost) + n(analysis.commission)]];
  return <aside className="sticky top-5 rounded-2xl border bg-white p-5 shadow-sm"><div className="mb-4 flex items-center justify-between"><div><h3 className="font-black text-cyan-800">Canlı maliyet ve kârlılık</h3><p className="text-xs text-slate-500">Seçimler değiştikçe anlık hesaplanır.</p></div><span className="flex items-center gap-1 text-xs font-bold text-emerald-600"><span className="h-2 w-2 rounded-full bg-emerald-500" />Canlı</span></div><div className="space-y-3"><SideMetric icon={ClipboardList} label="Toplam maliyet" value={formatCurrency(analysis.totalCost)} /><SideMetric icon={FileText} label="Mevcut satış" value={formatCurrency(analysis.salePrice)} /><SideMetric icon={PackagePlus} label="Tahmini net kâr" value={formatCurrency(analysis.profit)} hint={`%${analysis.netMargin.toFixed(1)} kâr`} tone="good" /><SideMetric icon={ShieldCheck} label="Net marj" value={`%${analysis.netMargin.toFixed(1)}`} hint="kâr / satış" /><SideMetric icon={Boxes} label="Markup" value={`%${analysis.markup.toFixed(1)}`} hint="kâr / maliyet" /></div><div className="mt-5 border-t pt-4"><h4 className="text-sm font-black">Maliyet kırılımı</h4><div className="mt-3 space-y-2">{breakdown.map(([label, value]: Any) => <div key={label} className="flex justify-between text-sm"><span className="text-slate-600">{label}</span><b>{formatCurrency(n(value))}</b></div>)}<div className="flex justify-between border-t pt-3 text-sm font-black"><span>Toplam maliyet</span><b>{formatCurrency(analysis.totalCost)}</b></div></div></div><PricingForm data={data} set={set} compact /><div className="mt-5"><p className="mb-2 text-xs font-black uppercase tracking-wide text-cyan-800">Önerilen kit satış fiyatları</p><div className="grid grid-cols-3 gap-2">{analysis.suggestions.map((row: Any) => <button key={row.margin} onClick={() => set('sale_price', row.salePrice)} className="rounded-xl border bg-white p-3 text-center hover:border-cyan-400 hover:bg-cyan-50"><span className="block text-[11px] text-slate-500">%{row.margin} markup</span><b className="text-sm">{formatCurrency(row.salePrice)}</b></button>)}</div></div><button disabled={saving} onClick={submit} className="mt-5 w-full rounded-xl bg-cyan-700 py-3 text-sm font-black text-white shadow-sm disabled:opacity-50"><Save className="mr-2 inline h-4 w-4" />Kaydet ve hesapla</button><div className="mt-4 rounded-xl bg-slate-50 p-4 text-xs text-slate-500"><ShieldCheck className="mr-2 inline h-4 w-4" />Kaydettikten sonra kit düzenlenebilir ve tekliflerde kullanılabilir.</div></aside>;
}

function SideMetric({ icon: Icon, label, value, hint, tone }: Any) {
  return <div className="flex items-center gap-3 rounded-xl border bg-white p-3 shadow-sm"><div className={`rounded-xl p-2 ${tone === 'good' ? 'bg-emerald-50 text-emerald-700' : 'bg-blue-50 text-blue-700'}`}><Icon className="h-4 w-4" /></div><div><p className="text-xs font-bold text-slate-500">{label}</p><b className="text-lg text-slate-900">{value}</b>{hint && <p className="text-xs text-emerald-600">{hint}</p>}</div></div>;
}

function PricingForm({ data, set }: Any) { const fields = [['target_margin', 'Hedef markup %'], ['sale_price', 'Manuel profil satış'], ['cutting_cost', 'Kesim maliyeti'], ['labour_cost', 'İşçilik'], ['packaging_cost', 'Paketleme'], ['other_cost', 'Diğer üretim'], ['commission_rate', 'Komisyon %'], ['payment_cost', 'Ödeme maliyeti'], ['shipping_cost', 'Kargo katkısı'], ['vat_rate', 'KDV %']]; return <section className="rounded-2xl bg-slate-900 p-5 text-white"><h3 className="font-black">Fiyatlandırma</h3><p className="mt-1 text-xs text-slate-300">Kâr sadece profil/üretim hizmetine uygulanır. Bağlantı elemanları ürün kartındaki satış fiyatını korur.</p><div className="mt-4 grid grid-cols-2 gap-2">{fields.map(([key, label]) => <label key={key} className="text-xs text-slate-300">{label}<input type="number" step="0.01" value={data[key] || 0} onChange={e => set(key, e.target.value)} className="mt-1 w-full rounded border border-white/10 bg-white/10 p-2 text-white" /></label>)}</div></section>; }

function LiveCostPanel({ analysis }: Any) { return <section className="rounded-2xl border border-cyan-200 bg-cyan-50 p-5 lg:col-span-2"><div className="flex items-baseline justify-between"><div><h3 className="font-black text-cyan-950">Canlı maliyet ve kârlılık</h3><p className="mt-1 text-sm text-cyan-900">Miktar, kesim veya fiyat değiştiğinde anlık güncellenir.</p></div><b className="text-lg text-cyan-800">{formatCurrency(analysis.totalCost)}</b></div><div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><LiveMetric label="Toplam maliyet" value={formatCurrency(analysis.totalCost)} /><LiveMetric label="Mevcut satış" value={formatCurrency(analysis.salePrice)} /><LiveMetric label="Tahmini net kâr" value={formatCurrency(analysis.profit)} tone={analysis.profit >= 0 ? 'good' : 'bad'} /><LiveMetric label="Net marj" value={`%${analysis.netMargin.toFixed(1)}`} hint="kâr / satış" /><LiveMetric label="Markup" value={`%${analysis.markup.toFixed(1)}`} hint="kâr / maliyet" /></div><div className="mt-4 border-t border-cyan-200 pt-3"><p className="text-xs font-black uppercase tracking-wide text-cyan-800">Önerilen kit satış fiyatı</p><div className="mt-2 grid grid-cols-3 gap-2">{analysis.suggestions.map((row: Any) => <div className="rounded-lg bg-white p-2 text-center text-sm" key={row.margin}><span className="block text-xs text-slate-500">%{row.margin} markup</span><b>{formatCurrency(row.salePrice)}</b></div>)}</div></div></section>; }
function LiveMetric({ label, value, hint, tone }: Any) { return <div className={`rounded-xl bg-white p-3 ${tone === 'bad' ? 'text-red-700' : tone === 'good' ? 'text-emerald-700' : ''}`}><p className="text-xs text-slate-500">{label}</p><b className="mt-1 block">{value}</b>{hint && <small className="text-slate-400">{hint}</small>}</div>; }
function CompatibilityNotice({ rows }: Any) { if (!rows?.length) return null; const hasIssue = rows.some((row: Any) => row.status !== 'uyumlu'); return <section className={`rounded-2xl border p-4 lg:col-span-3 ${hasIssue ? 'border-amber-300 bg-amber-50' : 'border-emerald-200 bg-emerald-50'}`}><h3 className="font-black">Profil - bağlantı elemanı uyumluluğu</h3><div className="mt-2 space-y-2">{rows.map((row: Any) => <div key={row.product_id} className="flex flex-wrap items-center justify-between gap-2 text-sm"><span><b className={row.status === 'uyumsuz' ? 'text-red-700' : row.status === 'şüpheli' ? 'text-amber-700' : 'text-emerald-700'}>{row.label}</b> · {row.reason}</span>{row.status !== 'uyumlu' && <span className="rounded bg-white px-2 py-1 text-xs text-slate-600">Manuel doğrulama ile devam edebilirsiniz</span>}</div>)}</div></section>; }

function SearchMaterial({ title, description, query, setQuery, results, add, items, update, remove, complement = false, catalogLabel = 'Katalog' }: Any) { return <section className="rounded-2xl border bg-white p-5 lg:col-span-3"><h3 className="font-black">{title}</h3><p className="mt-1 text-sm text-slate-500">{description}</p><div className="relative mt-3"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Katalogda ara..." className="w-full rounded-lg border py-2.5 pl-9" /></div><div className="mt-3 rounded-xl border bg-slate-50 p-3"><div className="mb-2 flex items-center justify-between"><p className="text-xs font-black uppercase tracking-wide text-slate-500">{catalogLabel}</p><small className="text-slate-400">{results.length} sonuç</small></div><div className="grid gap-2 md:grid-cols-2 xl:grid-cols-3">{results.map((item: Any) => <button key={item.id} onClick={() => add(item)} className="flex min-h-16 justify-between rounded-lg border bg-white p-3 text-left text-sm hover:border-cyan-400 hover:bg-cyan-50"><span><b className="block">{item.title || item.name}</b><small className="text-slate-400">{complement ? [item.category, item.supplier].filter(Boolean).join(' · ') : [item.sku, item.pipe_size || item.normalized_pipe_size].filter(Boolean).join(' · ')}</small></span><span className="shrink-0 pl-3 text-right font-bold text-slate-600">{complement ? `${formatCurrency(n(item.purchase_price))}/${unitLabel(item.unit)}` : `stok ${item.central_stock || 0}`}</span></button>)}{!results.length && <div className="rounded-lg bg-white p-4 text-sm text-slate-400 md:col-span-2 xl:col-span-3">Bu katalog için uygun ürün bulunamadı.</div>}</div></div><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[680px] text-sm"><thead className="border-b text-left text-xs uppercase text-slate-500"><tr><th className="pb-2">Ürün</th><th className="pb-2 text-right">Miktar</th><th className="pb-2 text-right">Birim</th><th className="pb-2 text-right">Birim alış</th><th className="pb-2 text-right">Satış / tutar</th><th /></tr></thead><tbody>{items.map((item: Any, index: number) => { const price = complement ? n(item.purchase_price_snapshot ?? item.purchase_price) : n(item.purchase_cost); const sale = complement ? n(item.quantity) * price : n(item.sale_price); return <tr key={item.product_id || item.complementary_product_id} className="border-b"><td className="py-3"><b>{item.title || item.name || item.product_name_snapshot}</b><p className="text-xs text-slate-400">{item.supplier || item.supplier_snapshot || item.sku || ''}</p></td><td className="text-right"><input type="number" step="0.01" min="0.01" value={item.quantity} onChange={e => update(index, e.target.value)} className="w-20 rounded border p-2 text-right" /></td><td className="text-right">{complement ? unitLabel(item.unit_snapshot || item.unit) : 'adet'}</td><td className="text-right">{formatCurrency(price)}</td><td className="text-right font-bold">{formatCurrency(sale)}</td><td className="text-right"><button onClick={() => remove(index)} aria-label="Kalemi sil"><X className="h-4 w-4" /></button></td></tr>; })}</tbody></table></div></section>; }

export function EnhancedComplementaryCatalog({ items, reload, onDirtyChange }: Any) {
  const empty = { name: '', category: '', description: '', supplier: '', supplier_reference: '', notes: '', unit: 'adet', purchase_price: '', unit_weight_kg: '', is_active: true, images: [] };
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('Tümü');
  const [form, setForm] = useState<Any | null>(null);
  const [images, setImages] = useState<File[]>([]);
  const [formDirty, setFormDirty] = useState(false);
  const [saving, setSaving] = useState(false);
  const [savedMessage, setSavedMessage] = useState('');
  const isDirty = formDirty || images.length > 0;
  useEffect(() => { onDirtyChange?.(isDirty); return () => onDirtyChange?.(false); }, [isDirty, onDirtyChange]);
  const categories = useMemo(() => ['Tümü', ...Array.from(new Set<string>(items.map((item: Any) => String(item.category || '')).filter(Boolean)))], [items]);
  const rows = items.filter((item: Any) => (!query || [item.name, item.category, item.supplier, item.supplier_reference].some(value => String(value || '').toLowerCase().includes(query.toLowerCase()))) && (category === 'Tümü' || item.category === category));
  const closeForm = () => {
    if (isDirty && !confirm('Kaydedilmemiş tamamlayıcı ürün değişiklikleri var. Çıkmak istiyor musunuz?')) return;
    setForm(null); setImages([]); setSavedMessage(''); setFormDirty(false);
  };
  const save = async () => {
    if (!form?.name) return alert('Ürün adı zorunludur.');
    setSaving(true);
    try {
      const payload = { ...form, purchase_price: n(form.purchase_price), unit_weight_kg: n(form.unit_weight_kg) };
      const saved = form.id ? await api.put(`/kits/complementary-products/${form.id}`, payload) : await api.post('/kits/complementary-products', payload);
      if (images.length) {
        const body = new FormData();
        images.forEach(file => body.append('images', file));
        await api.upload(`/kits/complementary-products/${saved.id}/images`, body);
      }
      await reload();
      setForm({ ...saved, purchase_price: saved.purchase_price ?? '', unit_weight_kg: saved.unit_weight_kg ?? '' });
      setImages([]);
      setFormDirty(false);
      setSavedMessage(`${saved.name} kaydedildi.`);
    } catch (error: Any) {
      alert(error.message || 'Ürün kaydedilemedi.');
    } finally {
      setSaving(false);
    }
  };
  return <section className="space-y-4">
    <div className="rounded-2xl border bg-cyan-50 p-4 text-sm text-cyan-950"><b>Stoksuz dış malzeme kataloğu.</b> Bu ürünler normal Ürünler ekranına, merkezi stoğa veya satış ekranına girmez; yalnızca kit maliyeti ve ağırlığında kullanılır.</div>
    <div className="flex flex-col gap-3 md:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Ürün, kategori, tedarikçi veya referans ara" className="w-full rounded-xl border bg-white py-2.5 pl-9" /></div><select value={category} onChange={e => setCategory(e.target.value)} className="rounded-xl border bg-white px-3">{categories.map(value => <option key={value}>{value}</option>)}</select><button onClick={() => { setImages([]); setSavedMessage(''); setForm(empty); setFormDirty(true); }} className="rounded-xl bg-cyan-700 px-4 py-2 text-sm font-bold text-white"><Plus className="mr-1 inline h-4 w-4" />Tamamlayıcı ürün ekle</button></div>
    {savedMessage && <div className="flex items-center gap-2 rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm font-bold text-emerald-800"><CheckCircle2 className="h-5 w-5" />{savedMessage}</div>}
    {form && <div className="rounded-2xl border bg-white p-5 shadow-sm">
      <div className="mb-4 flex justify-between"><div><h3 className="font-black">{form.id ? 'Tamamlayıcı ürünü düzenle' : 'Yeni tamamlayıcı ürün'}</h3><p className="mt-1 text-sm text-slate-500">Birim, fiyat ve ağırlık net girilir; kaydedince bu ekranda kalır.</p></div><button onClick={closeForm}><X className="h-4 w-4" /></button></div>
      <div className="grid gap-4 lg:grid-cols-[240px_1fr]">
        <div className="space-y-3">
          <label className="group flex min-h-32 cursor-pointer items-center justify-center rounded-xl border border-dashed bg-slate-50 p-3 text-center text-sm text-slate-500 hover:border-cyan-500 hover:bg-cyan-50"><span><ImagePlus className="mx-auto mb-1 h-5 w-5" />Birden fazla fotoğraf ekle<small className="mt-1 block">JPG, PNG, WEBP · en fazla 12 dosya</small></span><input className="sr-only" type="file" multiple accept="image/jpeg,image/png,image/webp" onChange={event => { setImages(Array.from(event.target.files || [])); setFormDirty(true); }} /></label>
          <div className="grid grid-cols-3 gap-2">{(form.images || []).map((image: Any) => <img key={image.id || image.path} src={image.path} alt="" className="h-16 w-full rounded-lg object-cover" />)}{images.map(file => <img key={file.name} src={URL.createObjectURL(file)} alt="" className="h-16 w-full rounded-lg object-cover ring-2 ring-cyan-300" />)}{!form.images?.length && !images.length && <div className="col-span-3 rounded-lg bg-slate-50 p-3 text-center text-xs text-slate-400">Henüz fotoğraf yok.</div>}</div>
        </div>
        <div className="grid gap-3 md:grid-cols-3">
          {[['name', 'Ürün adı *', 'Örn. Montaj bandı'], ['category', 'Kategori', 'Örn. Vida / boya / conta'], ['supplier', 'Tedarikçi', 'Örn. ABC Metal'], ['supplier_reference', 'Tedarikçi referansı', 'Kod veya link'], ['purchase_price', `Birim alış fiyatı (₺ / ${unitLabel(form.unit)})`, 'Örn. 125'], ['unit_weight_kg', `Birim ağırlık (kg / ${unitLabel(form.unit)})`, 'Örn. 0.35']].map(([key, label, placeholder]) => <label key={key} className="text-xs font-bold text-slate-500">{label}<input type={key === 'purchase_price' || key === 'unit_weight_kg' ? 'number' : 'text'} step="0.01" value={form[key] ?? ''} onChange={e => { setSavedMessage(''); setFormDirty(true); setForm({ ...form, [key]: e.target.value }); }} placeholder={placeholder} className="mt-1 w-full rounded-lg border p-2.5 text-sm font-normal text-slate-900" /></label>)}
          <label className="text-xs font-bold text-slate-500">Fiyat birimi<select value={form.unit} onChange={e => { setFormDirty(true); setForm({ ...form, unit: e.target.value }); }} className="mt-1 w-full rounded-lg border p-2.5 text-sm font-normal text-slate-900"><option value="adet">Adet bazlı</option><option value="metre">Metre bazlı</option><option value="m2">m² bazlı</option></select></label>
        </div>
      </div>
      <div className="mt-3 grid gap-3 md:grid-cols-2"><label className="text-xs font-bold text-slate-500">Açıklama<textarea value={form.description || ''} onChange={e => { setSavedMessage(''); setFormDirty(true); setForm({ ...form, description: e.target.value }); }} placeholder="Müşteri veya üretim için kısa açıklama" className="mt-1 h-20 w-full rounded-lg border p-2.5 text-sm font-normal text-slate-900" /></label><label className="text-xs font-bold text-slate-500">İç not<textarea value={form.notes || ''} onChange={e => { setSavedMessage(''); setFormDirty(true); setForm({ ...form, notes: e.target.value }); }} placeholder="Sadece panel içinde görünen not" className="mt-1 h-20 w-full rounded-lg border p-2.5 text-sm font-normal text-slate-900" /></label></div>
      <button disabled={saving} onClick={save} className="mt-3 rounded-lg bg-cyan-700 px-4 py-2 text-sm font-bold text-white disabled:opacity-50">{saving ? 'Kaydediliyor...' : 'Kaydet'}</button>
    </div>}
    <div className="overflow-x-auto rounded-2xl border bg-white shadow-sm"><table className="w-full min-w-[980px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase text-slate-500"><tr><th className="p-4">Görsel / ürün</th><th className="p-4">Kategori</th><th className="p-4">Tedarikçi</th><th className="p-4">Birim</th><th className="p-4">Alış fiyatı</th><th className="p-4">Birim ağırlık</th><th className="p-4">Son güncelleme</th><th className="p-4" /></tr></thead><tbody>{rows.map((item: Any) => <tr className="border-t" key={item.id}><td className="p-4"><div className="flex items-center gap-3">{item.cover_image ? <img src={item.cover_image} alt="" className="h-11 w-11 rounded-lg object-cover" /> : <div className="flex h-11 w-11 items-center justify-center rounded-lg bg-slate-100 text-slate-400"><ImagePlus className="h-4 w-4" /></div>}<span><b>{item.name}</b><small className="block text-slate-400">{item.supplier_reference || ''}{item.images?.length ? ` · ${item.images.length} fotoğraf` : ''}</small></span></div></td><td className="p-4">{item.category || '—'}</td><td className="p-4">{item.supplier || '—'}</td><td className="p-4">{unitLabel(item.unit)}</td><td className="p-4 font-bold">{formatCurrency(n(item.purchase_price))}/{unitLabel(item.unit)}</td><td className="p-4">{n(item.unit_weight_kg).toLocaleString('tr-TR')} kg/{unitLabel(item.unit)}</td><td className="p-4 text-xs text-slate-500">{new Date(item.updated_at).toLocaleDateString('tr-TR')}</td><td className="p-4 text-right"><button onClick={() => { setImages([]); setSavedMessage(''); setFormDirty(false); setForm(item); }} className="mr-3 text-cyan-700"><Pencil className="inline h-4 w-4" /></button><button onClick={async () => { if (confirm('Tamamlayıcı ürün silinsin mi?')) { try { await api.delete(`/kits/complementary-products/${item.id}`); await reload(); } catch (error: Any) { alert(error.message); } } }} className="text-slate-400 hover:text-red-600"><Trash2 className="inline h-4 w-4" /></button></td></tr>)}{!rows.length && <tr><td colSpan={8} className="p-12 text-center text-slate-400">Tamamlayıcı ürün bulunamadı.</td></tr>}</tbody></table></div>
  </section>;
}

export function EnhancedProfileEditor({ profile, back, save }: Any) {
  const [data, setData] = useState<Any>(profile); const [saved, setSaved] = useState(false); const [saving, setSaving] = useState(false); const [dirty, setDirty] = useState(false);
  const set = (key: string, value: unknown) => setData((old: Any) => ({ ...old, [key]: value }));
  const submit = async () => { if (!data.name) return alert('Profil adı zorunludur.'); setSaving(true); try { const result = await save(data); setData((old: Any) => ({ ...old, ...result })); setDirty(false); setSaved(true); } catch (error: Any) { alert(error.message || 'Profil kaydedilemedi.'); } finally { setSaving(false); } };
  const goBack = () => { if (dirty && !confirm('Kaydedilmemiş profil değişiklikleri var. Çıkmak istiyor musunuz?')) return; back(); };
  const Field = ({ name, label, type = 'text' }: Any) => <label className="text-xs font-bold text-slate-500">{label}<input type={type} step="0.01" value={data[name] ?? ''} onChange={e => { setSaved(false); setDirty(true); set(name, e.target.value); }} className="mt-1 w-full rounded-lg border p-2.5 text-sm font-normal text-slate-900" /></label>;
  return <div className="space-y-5"><button onClick={goBack} className="text-sm font-bold text-slate-600"><ArrowLeft className="mr-1 inline h-4 w-4" />Profillere dön</button><div className="flex flex-col justify-between gap-3 md:flex-row"><div><h2 className="text-2xl font-black">{data.id ? 'Profil detayı' : 'Yeni profil'}</h2><p className="mt-1 text-sm text-slate-500">Ölçü sınıfı sabit; renk, kaplama, et kalınlığı ve tedarikçi fiyatı varyant olarak yönetilir.</p></div><button disabled={saving} onClick={submit} className="rounded-xl bg-cyan-700 px-4 py-2 text-sm font-bold text-white disabled:opacity-50">{saving ? 'Kaydediliyor...' : 'Profili kaydet'}</button></div>{saved && <div className="flex items-center gap-2 rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm font-bold text-emerald-800"><CheckCircle2 className="h-5 w-5" />Profil başarıyla kaydedildi. Son güncelleme: {new Date().toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })}</div>}<div className="grid gap-5 lg:grid-cols-3"><section className="rounded-2xl border bg-white p-5 lg:col-span-2"><h3 className="font-black">Ölçü sınıfı</h3><p className="mt-1 text-sm text-slate-500">Katalog uyumluluğu bu alanlara göre çalışır.</p><div className="mt-4 grid gap-3 md:grid-cols-2"><Field name="name" label="Profil adı" /><Field name="shape" label="Form" /><Field name="dimension" label="Ölçü" /><Field name="material" label="Hammadde" /></div></section><section className="rounded-2xl border bg-cyan-50 p-5"><h3 className="font-black">Varsayılan maliyet</h3><p className="mt-1 text-sm text-slate-500">Tedarikçi teklifi yoksa kullanılır.</p><div className="mt-4 grid gap-3"><Field name="supplier" label="Tedarikçi" /><Field name="price_per_meter" label="₺ / metre" type="number" /></div></section><section className="rounded-2xl border bg-white p-5 lg:col-span-3"><h3 className="font-black">Varyant özellikleri</h3><p className="mt-1 text-sm text-slate-500">Aynı ölçü sınıfı içinde farklı et kalınlığı, kaplama, renk ve kaliteyi buradan ayırın.</p><div className="mt-4 grid gap-3 md:grid-cols-3"><Field name="thickness" label="Et kalınlığı" /><Field name="grade" label="Kalite / sınıf" /><Field name="color" label="Renk" /><Field name="finish" label="Kaplama / yüzey" /><Field name="weight_per_meter" label="kg / metre" type="number" /><Field name="stock_length_mm" label="Ham boy (mm)" type="number" /></div><label className="mt-3 block text-xs font-bold text-slate-500">Notlar<textarea value={data.notes || ''} onChange={e => { setSaved(false); setDirty(true); set('notes', e.target.value); }} className="mt-1 h-20 w-full rounded-lg border p-2.5 text-sm font-normal text-slate-900" /></label></section></div></div>;
}

export function EnhancedKitOverview({ kit, back, edit }: Any) {
  const analysis = kit.analysis || {}; const breakdown = analysis.breakdown || {}; const weights = analysis.weightBreakdown || {};
  const lines = [['Bağlantı elemanları', breakdown.partsCost], ['Profil hammaddesi', breakdown.profileMaterial], ['Tamamlayıcı ürünler', breakdown.complementaryCost], ['İşçilik', breakdown.labour], ['Paketleme', breakdown.packaging], ['Diğer gider', breakdown.other], ['Komisyon', breakdown.commission]];
  return <div className="space-y-5"><button onClick={back} className="text-sm font-bold text-slate-600"><ArrowLeft className="mr-1 inline h-4 w-4" />Kitlere dön</button><section className="overflow-hidden rounded-2xl border bg-white shadow-sm"><div className="flex flex-col gap-4 bg-slate-900 p-6 text-white md:flex-row">{kit.cover_image && <img src={kit.cover_image} alt="" className="h-24 w-32 rounded-xl object-cover" />}<div className="flex-1"><p className="text-xs font-black uppercase tracking-widest text-cyan-300">{kit.code || 'KIT'}</p><h2 className="mt-1 text-2xl font-black">{kit.name}</h2>{kit.description && <p className="mt-2 text-sm text-slate-300">{kit.description}</p>}</div><div className="flex h-fit flex-wrap gap-2"><button onClick={() => printKitPdf(kit, false)} className="rounded-xl bg-white px-3 py-2 text-sm font-bold text-slate-800"><Printer className="mr-1 inline h-4 w-4" />Müşteri PDF</button><button onClick={() => printKitPdf(kit, true)} className="rounded-xl border border-white/20 px-3 py-2 text-sm font-bold"><FileText className="mr-1 inline h-4 w-4" />İç maliyet PDF</button><button onClick={edit} className="rounded-xl border border-white/20 px-3 py-2 text-sm font-bold">Düzenle</button></div></div><div className="grid divide-y md:grid-cols-4 md:divide-x md:divide-y-0"><Metric title="Toplam maliyet" value={formatCurrency(n(analysis.baseCost))} hint="Kâr eklenmemiş" /><Metric title="Satış fiyatı" value={formatCurrency(n(analysis.salePrice))} hint="Kit teklifi" /><Metric title="Net kâr" value={formatCurrency(n(analysis.netProfit))} hint={`Marj %${n(analysis.margin).toFixed(1)}`} /><Metric title="Net ağırlık" value={`${n(weights.totalWeightKg).toFixed(2)} kg`} hint="Profil + parça + tamamlayıcı" /></div></section><div className="grid gap-5 lg:grid-cols-2"><section className="rounded-2xl border bg-white p-5"><h3 className="font-black">Fiyat ve ağırlık analizi</h3><table className="mt-3 w-full text-sm"><tbody>{lines.map(([label, value]) => <tr key={String(label)} className="border-b"><td className="py-2">{label}</td><td className="py-2 text-right font-bold">{formatCurrency(n(value))}</td></tr>)}<tr className="bg-cyan-50"><td className="p-3 font-black">Toplam maliyet</td><td className="p-3 text-right font-black">{formatCurrency(n(analysis.baseCost))}</td></tr></tbody></table><h4 className="mt-5 font-black">Ağırlık breakdown</h4><div className="mt-2 grid grid-cols-2 gap-2 text-sm"><span>Bağlantı elemanları</span><b className="text-right">{n(weights.connectionWeightKg).toFixed(2)} kg</b><span>Profil ({n(kit.weight_per_meter).toFixed(3)} kg/m)</span><b className="text-right">{n(weights.profileWeightKg).toFixed(2)} kg</b><span>Tamamlayıcı ürünler</span><b className="text-right">{n(weights.complementaryWeightKg).toFixed(2)} kg</b><span className="border-t pt-2 font-black">Toplam net ağırlık</span><b className="border-t pt-2 text-right">{n(weights.totalWeightKg).toFixed(2)} kg</b></div></section><section className="rounded-2xl border bg-white p-5"><h3 className="font-black">Profil ve kesim kartı</h3><p className="mt-2 text-lg font-bold">{kit.profile_name}</p><p className="text-sm text-slate-500">{kit.profile_material} · {kit.dimension} · {kit.thickness || 'Kalınlık yok'} · {n(kit.weight_per_meter).toFixed(3)} kg/m</p><div className="mt-4 space-y-2">{kit.cuts?.length ? kit.cuts.map((cut: Any) => <div key={cut.id} className="flex justify-between rounded-lg bg-slate-50 px-3 py-2 text-sm"><span>{cut.label || 'Profil parçası'}</span><b>{cut.quantity} × {cut.length_mm} mm</b></div>) : <p className="text-sm text-slate-400">Kesim eklenmemiş.</p>}</div><h3 className="mt-5 font-black">Tamamlayıcı ürünler</h3>{kit.complementary_items?.length ? kit.complementary_items.map((item: Any) => <div className="mt-2 rounded-lg bg-amber-50 p-3 text-sm" key={item.id}><div className="flex justify-between"><b>{item.product_name_snapshot}</b><b>{formatCurrency(n(item.quantity) * n(item.purchase_price_snapshot))}</b></div><p className="mt-1 text-slate-600">{item.quantity} {unitLabel(item.unit_snapshot)} · {n(item.quantity * item.unit_weight_kg_snapshot).toFixed(2)} kg</p></div>) : <p className="mt-2 text-sm text-slate-400">Tamamlayıcı ürün eklenmemiş.</p>}</section></div></div>;
}

export function KitDetailV2({ kit, back, edit }: Any) {
  const a = kit.analysis || {}; const b = a.breakdown || {}; const w = a.weightBreakdown || {};
  const groups = [
    ['Malzeme maliyetleri', [['Bağlantı elemanları', b.partsCost], ['Profil hammaddesi', b.profileMaterial], ['Tamamlayıcı ürünler', b.complementaryCost]]],
    ['Üretim maliyetleri', [['Kesim', b.cutting], ['İşçilik', b.labour], ['Paketleme', b.packaging], ['Diğer üretim', b.other]]],
    ['Ticari / satış maliyetleri', [['Pazaryeri komisyonu', b.commission], ['Ödeme maliyeti', b.payment], ['Kargo katkısı', b.shipping]]],
  ];
  const bom = [
    ...(kit.items || []).map((item: Any) => ({ group: 'Bağlantı elemanı', name: item.title || item.name, quantity: `${item.quantity} adet`, unit: n(item.purchase_cost), total: n(item.quantity) * n(item.purchase_cost) })),
    { group: 'Profil', name: `${kit.profile_name} · ${kit.dimension}`, quantity: `${n(a.profileMeters).toFixed(2)} m`, unit: n(kit.effective_price_per_meter), total: n(a.profileCost) },
    ...(kit.complementary_items || []).map((item: Any) => ({ group: 'Tamamlayıcı', name: item.product_name_snapshot, quantity: `${item.quantity} ${unitLabel(item.unit_snapshot)}`, unit: n(item.purchase_price_snapshot), total: n(item.quantity) * n(item.purchase_price_snapshot) })),
  ];
  return <div className="space-y-5"><button onClick={back} className="text-sm font-bold text-slate-600"><ArrowLeft className="mr-1 inline h-4 w-4" />Kitlere dön</button><section className="overflow-hidden rounded-2xl border bg-white shadow-sm"><div className="flex flex-col gap-4 bg-slate-900 p-6 text-white md:flex-row">{kit.cover_image && <img src={kit.cover_image} alt="" className="h-24 w-32 rounded-xl object-cover" />}<div className="flex-1"><p className="text-xs font-black uppercase tracking-widest text-cyan-300">{kit.code || 'KIT'}</p><h2 className="mt-1 text-2xl font-black">{kit.name}</h2><p className="mt-2 text-sm text-slate-300">{kit.description || 'Açıklama eklenmemiş.'}</p></div><button onClick={edit} className="h-fit rounded-xl border border-white/20 px-3 py-2 text-sm font-bold">Düzenle</button></div><div className="grid divide-y md:grid-cols-4 md:divide-x md:divide-y-0"><Metric title="Toplam maliyet" value={formatCurrency(n(a.baseCost))} hint="Tüm maliyet grupları" /><Metric title="Satış fiyatı" value={formatCurrency(n(a.salePrice))} hint="Mevcut kit teklifi" /><Metric title="Net kâr" value={formatCurrency(n(a.netProfit))} hint={`Net marj %${n(a.margin).toFixed(1)}`} /><Metric title="Markup" value={`%${n(a.markup).toFixed(1)}`} hint="kâr / toplam maliyet" /></div></section><div className="grid gap-5 lg:grid-cols-3"><section className="rounded-2xl border bg-white p-5 lg:col-span-2"><h3 className="font-black">Profesyonel fiyat ve ağırlık analizi</h3><p className="mt-1 text-sm text-slate-500">Net marj = kâr / satış fiyatı. Markup = kâr / maliyet.</p><div className="mt-4 grid gap-3 md:grid-cols-3">{groups.map(([name, rows]: Any) => <div className="rounded-xl border p-3" key={name}><h4 className="text-sm font-black">{name}</h4>{rows.map(([label, value]: Any) => <div className="mt-2 flex justify-between text-sm" key={label}><span className="text-slate-600">{label}</span><b>{formatCurrency(n(value))}</b></div>)}</div>)}</div><div className="mt-4 grid grid-cols-2 gap-2 rounded-xl bg-slate-50 p-3 text-sm"><span>Bağlantı elemanı ağırlığı</span><b className="text-right">{n(w.connectionWeightKg).toFixed(2)} kg</b><span>Profil ağırlığı ({n(kit.weight_per_meter).toFixed(3)} kg/m)</span><b className="text-right">{n(w.profileWeightKg).toFixed(2)} kg</b><span>Tamamlayıcı ağırlığı</span><b className="text-right">{n(w.complementaryWeightKg).toFixed(2)} kg</b><span className="border-t pt-2 font-black">Toplam net ağırlık</span><b className="border-t pt-2 text-right">{n(w.totalWeightKg).toFixed(2)} kg</b></div></section><section className="rounded-2xl border bg-white p-5"><h3 className="font-black">Kârlılık metrikleri</h3><div className="mt-4 space-y-3"><div className="rounded-lg bg-cyan-50 p-3"><span className="text-sm">Net marj</span><b className="float-right text-cyan-800">%{n(a.margin).toFixed(1)}</b><p className="mt-1 text-xs text-slate-500">Kârın satış fiyatı içindeki oranı.</p></div><div className="rounded-lg bg-emerald-50 p-3"><span className="text-sm">Markup</span><b className="float-right text-emerald-800">%{n(a.markup).toFixed(1)}</b><p className="mt-1 text-xs text-slate-500">Kârın toplam maliyete oranı.</p></div><div className="rounded-lg bg-slate-50 p-3"><span className="text-sm">Net kâr</span><b className="float-right">{formatCurrency(n(a.netProfit))}</b></div></div></section></div><section className="overflow-x-auto rounded-2xl border bg-white p-5"><div><h3 className="font-black">Malzeme Listesi / BOM</h3><p className="mt-1 text-sm text-slate-500">Bu kiti üretmek için gereken tüm malzemeler.</p></div><table className="mt-4 w-full min-w-[700px] text-sm"><thead className="border-b text-left text-xs uppercase text-slate-500"><tr><th className="pb-2">Grup</th><th className="pb-2">Malzeme</th><th className="pb-2 text-right">Miktar</th><th className="pb-2 text-right">Birim maliyet</th><th className="pb-2 text-right">Toplam maliyet</th></tr></thead><tbody>{bom.map((row: Any, index: number) => <tr className="border-b" key={`${row.group}-${index}`}><td className="py-3"><span className="rounded bg-slate-100 px-2 py-1 text-xs font-bold">{row.group}</span></td><td className="py-3 font-medium">{row.name}</td><td className="py-3 text-right">{row.quantity}</td><td className="py-3 text-right">{formatCurrency(row.unit)}</td><td className="py-3 text-right font-bold">{formatCurrency(row.total)}</td></tr>)}</tbody></table><div className="mt-3 text-right text-sm">Malzeme toplamı: <b>{formatCurrency(n(b.partsCost) + n(b.profileMaterial) + n(b.complementaryCost))}</b></div></section><section className="rounded-2xl border bg-white p-5"><h3 className="font-black">Kesim Listesi</h3><p className="mt-1 text-sm text-slate-500">Profillerin nasıl kesileceği; BOM’dan bağımsız üretim talimatı.</p><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[600px] text-sm"><thead className="border-b text-left text-xs uppercase text-slate-500"><tr><th className="pb-2">Profil</th><th className="pb-2">Parça</th><th className="pb-2 text-right">Adet</th><th className="pb-2 text-right">Uzunluk</th></tr></thead><tbody>{kit.cuts?.length ? kit.cuts.map((cut: Any) => <tr className="border-b" key={cut.id}><td className="py-3">{kit.profile_name} · {kit.dimension}</td><td className="py-3">{cut.label || 'Profil parçası'}</td><td className="py-3 text-right">{cut.quantity}</td><td className="py-3 text-right font-bold">{cut.length_mm} mm</td></tr>) : <tr><td colSpan={4} className="py-8 text-center text-slate-400">Kesim eklenmemiş.</td></tr>}</tbody></table></div></section></div>;
}

function Metric({ title, value, hint }: { title: string; value: string; hint: string }) { return <div className="p-5"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">{title}</p><p className="mt-2 text-xl font-black">{value}</p><p className="mt-1 text-xs text-slate-500">{hint}</p></div>; }

function esc(value: unknown) { return String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char] || char)); }

function printKitPdf(kit: Any, internal: boolean) {
  const a = kit.analysis || {}; const w = a.weightBreakdown || {}; const unit = (value: string) => unitLabel(value);
  const connectionRows = (kit.items || []).map((item: Any) => internal ? `<tr><td>${esc(item.title || item.name)}</td><td>${n(item.quantity)}</td><td>${formatCurrency(n(item.purchase_cost))}</td><td>${formatCurrency(n(item.quantity) * n(item.purchase_cost))}</td></tr>` : `<tr><td>${esc(item.title || item.name)}</td><td>${n(item.quantity)}</td><td>${formatCurrency(n(item.sale_price))}</td><td>${formatCurrency(n(item.quantity) * n(item.sale_price))}</td></tr>`).join('');
  const complementRows = (kit.complementary_items || []).map((item: Any) => internal ? `<tr><td>${esc(item.product_name_snapshot)}</td><td>${n(item.quantity)} ${unit(item.unit_snapshot)}</td><td>${formatCurrency(n(item.purchase_price_snapshot))}</td><td>${formatCurrency(n(item.quantity) * n(item.purchase_price_snapshot))}</td></tr>` : `<tr><td>${esc(item.product_name_snapshot)}</td><td>${n(item.quantity)} ${unit(item.unit_snapshot)}</td><td colspan="2">Kit fiyatına dahildir</td></tr>`).join('');
  const cutRows = (kit.cuts || []).map((cut: Any) => `<tr><td>${esc(cut.label || 'Profil parçası')}</td><td>${n(cut.quantity)} adet</td><td>${n(cut.length_mm)} mm</td></tr>`).join('');
  const customer = `${kit.description ? `<section class="note"><b>Açıklama</b><p>${esc(kit.description)}</p></section>` : ''}<h2>Bağlantı elemanları</h2><table><thead><tr><th>Ürün</th><th>Adet</th><th>Birim fiyat</th><th>Tutar</th></tr></thead><tbody>${connectionRows || '<tr><td colspan="4">Bağlantı elemanı yok.</td></tr>'}</tbody></table><h2>Kesilmiş profil parçaları</h2><table><thead><tr><th>Parça</th><th>Adet</th><th>Boy</th></tr></thead><tbody>${cutRows || '<tr><td colspan="3">Kesim eklenmemiş.</td></tr>'}</tbody></table><h2>Tamamlayıcı ürünler</h2><table><thead><tr><th>Ürün</th><th>Miktar</th><th colspan="2">Durum</th></tr></thead><tbody>${complementRows || '<tr><td colspan="4">Tamamlayıcı ürün yok.</td></tr>'}</tbody></table><table class="summary"><tbody><tr><td>Profil</td><td>${esc(kit.profile_name)} · ${esc(kit.dimension)} · ${n(kit.weight_per_meter).toFixed(3)} kg/m</td></tr><tr><td>Toplam net ağırlık</td><td>${n(w.totalWeightKg).toFixed(2)} kg</td></tr><tr><td>KDV</td><td>%${n(kit.vat_rate)}</td></tr><tr class="total"><td>Teklif satış fiyatı</td><td>${formatCurrency(n(a.salePrice))}</td></tr></tbody></table>`;
  const internalBody = `<h2>Bağlantı elemanları - alış maliyeti</h2><table><thead><tr><th>Ürün</th><th>Adet</th><th>Birim alış</th><th>Tutar</th></tr></thead><tbody>${connectionRows || '<tr><td colspan="4">Bağlantı elemanı yok.</td></tr>'}</tbody></table><h2>Tamamlayıcı ürünler - alış maliyeti</h2><table><thead><tr><th>Ürün</th><th>Miktar</th><th>Birim alış</th><th>Tutar</th></tr></thead><tbody>${complementRows || '<tr><td colspan="4">Tamamlayıcı ürün yok.</td></tr>'}</tbody></table><h2>Profil ve kesimler</h2><div class="profile"><b>${esc(kit.profile_name)}</b><span>${esc(kit.profile_material)} · ${esc(kit.dimension)} · ${esc(kit.thickness || '')}</span><span>Profil ağırlığı: ${n(kit.weight_per_meter).toFixed(3)} kg/m · toplam ${n(w.profileWeightKg).toFixed(2)} kg</span><span>Profil alış maliyeti: ${formatCurrency(n(kit.effective_price_per_meter))}/m</span></div><table><thead><tr><th>Kesilmiş parça</th><th>Adet</th><th>Boy</th></tr></thead><tbody>${cutRows || '<tr><td colspan="3">Kesim eklenmemiş.</td></tr>'}</tbody></table><h2>Güvenilir maliyet özeti</h2><table class="summary"><tbody><tr><td>Bağlantı elemanları</td><td>${formatCurrency(n(a.partsCost))}</td></tr><tr><td>Profil hammaddesi</td><td>${formatCurrency(n(a.profileCost))}</td></tr><tr><td>Tamamlayıcı ürünler</td><td>${formatCurrency(n(a.complementaryCost))}</td></tr><tr><td>İşçilik / paketleme / diğer</td><td>${formatCurrency(n(kit.labour_cost) + n(kit.packaging_cost) + n(kit.other_cost))}</td></tr><tr><td>Komisyon</td><td>${formatCurrency(n(a.commission))}</td></tr><tr class="total"><td>Toplam maliyet</td><td>${formatCurrency(n(a.baseCost))}</td></tr><tr class="total accent"><td>Kit satış fiyatı</td><td>${formatCurrency(n(a.salePrice))}</td></tr><tr><td>Net kâr</td><td>${formatCurrency(n(a.netProfit))}</td></tr></tbody></table>`;
  const popup = window.open('', '_blank'); if (!popup) return;
  popup.document.write(`<!doctype html><html><head><title>${esc(kit.name)}</title><style>@page{margin:16mm}*{box-sizing:border-box}body{font:13px Arial,sans-serif;color:#172033;max-width:820px;margin:auto;line-height:1.45}header{display:flex;justify-content:space-between;gap:20px;border-bottom:4px solid #0e7490;padding-bottom:18px}h1{margin:4px 0;font-size:28px}h2{font-size:16px;margin:28px 0 9px;color:#0f3e50}small,.muted{color:#64748b}table{width:100%;border-collapse:collapse;margin-top:8px}th{background:#e9f7f9;color:#174657;text-align:left;font-size:10px;letter-spacing:.04em;text-transform:uppercase}td,th{padding:10px;border-bottom:1px solid #dce3e8;vertical-align:top}.summary{margin:26px 0 0 auto;max-width:480px}.summary td:last-child{text-align:right;font-weight:700}.total td{background:#eef4f7;font-size:15px;font-weight:800}.accent td{background:#dff5f7;color:#084a5b}.note{margin-top:22px;border-left:4px solid #0e7490;background:#f1f7f8;padding:12px}.note p{margin:5px 0 0}.profile{display:grid;gap:4px;background:#f7fafc;border:1px solid #dce3e8;border-radius:8px;padding:12px}.profile span{color:#52616f}@media print{button{display:none}}</style></head><body><header><div><small>DSDST PANEL · ${internal ? 'İÇ MALİYET RAPORU' : 'MÜŞTERİ TEKLİFİ'}</small><h1>${esc(kit.name)}</h1><small>Kit kodu: ${esc(kit.code || '—')}</small></div><div class="muted">${new Date().toLocaleDateString('tr-TR')}</div></header>${internal ? internalBody : customer}</body></html>`); popup.document.close(); popup.focus(); setTimeout(() => popup.print(), 200);
}
